const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (data.length === 0) process.exit(0);

const n = data[0];
const h = data.slice(1, n + 1);

const leftMax = new Array(n);
let max = 0;

for (let i = 0; i < n; i++) {
    if (h[i] > max) max = h[i];
    leftMax[i] = max;
}

let rightMax = 0;
let answer = 0;

for (let i = n - 1; i >= 0; i--) {
    if (h[i] > rightMax) rightMax = h[i];
    const waterLevel = Math.min(leftMax[i], rightMax);
    if (waterLevel - h[i] >= 1) answer++;
}

console.log(answer);
